const D = { corrosion: .55, scale: 1, energy: .6, density: .5, hue: 0, speed: 1, x: .5, y: .5, alpha: 1, style: 'verdigris', act: 'creep', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hz=i=>{const s=Math.sin(i*269.5+78.233)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=(((h%360)+360)%360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const corr=cl(P.corrosion,0,1.6), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4);
const en=cl(P.energy,0,1)*(.5+.6*K.intensity);
const T=K.t*spd, H=md(P.hue,360);

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;
const kick=Math.min(1, K.pulse*.45+S.bass*.6);

// ---- the plate grid ----
const GW=132, GH=cl(Math.round(132*Hh/Math.max(1,W)),40,132), NC=GW*GH;
const rkey=GH+'|'+P.seed+'|'+Math.round(sc*8);
if(!S.age||S.n!==NC){ S.age=new Float32Array(NC); S.n=NC; S.rk=null; S.nuc=null; }
if(S.rk!==rkey){
  S.rk=rkey; S.res=new Float32Array(NC);
  const f1=5.4/sc, f2=13.1/sc, f3=27.3/sc, o1=fr(1)*40, o2=fr(2)*40, o3=fr(3)*40;
  for(let j=0;j<GH;j++){ const y=j/GH;
    for(let i=0;i<GW;i++){ const x=i/GW;
      let v=.5+.30*Math.sin(x*f1+o1)*Math.cos(y*f1*1.21-o1)
             +.17*Math.sin(x*f2*1.13-o2)*Math.cos(y*f2+o2)
             +.09*Math.sin(x*f3+o3)*Math.cos(y*f3*.87-o3);
      S.res[j*GW+i]=cl(v,0,1); } }
  if(S.nuc!==P.seed){ S.nuc=P.seed; S.age.fill(0); const NN=5+Math.round(dens*9);
    for(let k=0;k<NN;k++){ const ci=Math.floor(fr(k*7)*GW), cj=Math.floor(fr(k*7+1)*GH);
      for(let dj=-2;dj<=2;dj++) for(let di=-2;di<=2;di++){
        const ii=(ci+di+GW)%GW, jj=cl(cj+dj,0,GH-1); S.age[jj*GW+ii]=1; } } }
}
const age=S.age, res=S.res;

// ---- creep: real-seconds integration, tolerant of t0 resets ----
if(S.pt==null||K.t<S.pt) S.pt=K.t;
let dt=cl(K.t-S.pt,0,.09); S.pt=K.t;
let gr=spd*(act==='bloom'?1.35:0.55)*(0.55+0.8*K.intensity);
const flakeThr=act==='bloom'?0.986:0.9975;
const tick=Math.floor(K.t*4);
for(let j=0;j<GH;j++){
  const jm=(j>0?j-1:0)*GW, jp=(j<GH-1?j+1:GH-1)*GW, jc=j*GW;
  for(let i=0;i<GW;i++){
    const R=res[jc+i]; if(R>.88) continue;               // permanent bare-metal islands
    let a=age[jc+i];
    if(a>0){ a+=dt*gr*(.30+.85*(1-R)); }
    else{
      const im=(i>0?i-1:GW-1), ip=(i<GW-1?i+1:0);
      let nm=age[jc+im]; const b1=age[jc+ip], b2=age[jm+i], b3=age[jp+i];
      if(b1>nm)nm=b1; if(b2>nm)nm=b2; if(b3>nm)nm=b3;
      if(nm>.22) a+=dt*gr*(.45+1.15*(1-R))*(nm-.18);
    }
    if(a>.94 && hz(jc+i+tick*7919)>flakeThr) a=0;        // crust spalls -> fresh metal
    age[jc+i]=a>1?1:a;
  }
}
// 'strip' act: a slow front strips the plate back to bare metal every ~90s
if(act==='strip'){ const sx=((T*.011)%1+1)%1*GW;
  for(let i=0;i<GW;i++){ const d=Math.abs(i-sx); if(d<GW*.035||d>GW*(1-.035))
    for(let j=0;j<GH;j++) age[j*GW+i]*=.86; } }

// ---- tone ramp LUT (rebuilt only on style/hue change) ----
const lkey=sty+'|'+Math.round(H);
if(!S.lut||S.lk!==lkey){
  let st;
  if(sty==='rust') st=[[0,210,9,44],[.28,16,42,23],[.56,20,78,52],[.82,28,82,72],[1,38,58,60]];
  else if(sty==='silver_tarnish') st=[[0,208,4,76],[.26,46,46,66],[.5,316,46,52],[.72,232,54,40],[.88,268,40,22],[1,250,26,11]];
  else if(sty==='lichen') st=[[0,40,7,50],[.32,84,15,30],[.58,96,28,58],[.84,48,46,72],[1,60,16,84]];
  else if(sty==='mineral') st=[[0,250,72,16],[.25,208,74,34],[.5,150,72,48],[.75,52,78,66],[1,8,80,80]];
  else st=[[0,22,56,52],[.24,13,64,32],[.5,200,32,22],[.72,168,54,50],[.9,156,44,66],[1,150,30,78]];
  S.lut=new Uint8Array(256*3);
  for(let i=0;i<256;i++){ const t=i/255; let k=0; while(k<st.length-2&&t>st[k+1][0])k++;
    const a=st[k], b=st[k+1], f=cl((t-a[0])/Math.max(1e-4,b[0]-a[0]),0,1);
    const c=hsb2rgb(a[1]+(b[1]-a[1])*f+H, a[2]+(b[2]-a[2])*f, a[3]+(b[3]-a[3])*f);
    S.lut[i*3]=c[0]; S.lut[i*3+1]=c[1]; S.lut[i*3+2]=c[2]; }
  S.lk=lkey; }
const lut=S.lut, band=(sty==='mineral');

// ---- raking light sweeping the bare metal: the second motion floor ----
const lp=cl(P.x,0,1)+.46*Math.sin(T*.081)+.19*Math.sin(T*.191+1.3);
const specA=(38+52*en)*(1+.35*kick*en);

if(!S.buf||S.bw!==GW||S.bh!==GH){ if(S.buf&&S.buf.remove)S.buf.remove(); S.buf=createGraphics(GW,GH); S.bw=GW; S.bh=GH; }
const buf=S.buf; buf.loadPixels();
const px=buf.pixels;
for(let j=0;j<GH;j++){
  const jm=(j>0?j-1:0)*GW, jp=(j<GH-1?j+1:GH-1)*GW, jc=j*GW;
  for(let i=0;i<GW;i++){
    const a=age[jc+i], R=res[jc+i];
    let ox=cl(a*(.35+corr*1.30),0,1);
    let idx=(ox*255)|0; if(idx>255)idx=255;
    let r=lut[idx*3], g=lut[idx*3+1], b=lut[idx*3+2];
    // crust mottle + relief rim from the oxide gradient
    const im=(i>0?i-1:0), ip=(i<GW-1?i+1:GW-1);
    const rim=(age[jc+im]-age[jc+ip])*46*ox + (age[jm+i]-age[jp+i])*26*ox;
    let m=(.80+.42*R)*(1+rim*.012);
    // bare metal is specular; crust is matte
    const sp=Math.pow(cl(1-Math.abs(i/GW-lp)*3.1,0,1),3)*(1-ox)*specA;
    if(band){ const q=(ox*9)%1; if(q<.11) m*=1.55; }
    let rr=r*m+sp, gg=g*m+sp*.97, bb=b*m+sp*1.04;
    const o=(jc+i)*4;
    px[o]=rr>255?255:rr; px[o+1]=gg>255?255:gg; px[o+2]=bb>255?255:bb; px[o+3]=255;
  }
}
buf.updatePixels();
drawingContext.imageSmoothingEnabled=true;
image(buf,0,0,W,Hh);

const dc=drawingContext, oldOp=dc.globalCompositeOperation;
const smp=(x,y)=>age[cl(Math.floor(y*GH),0,GH-1)*GW+cl(Math.floor(x*GW),0,GW-1)];

// ---- brushed / cast surface texture over the whole plate (cached) ----
const tkey=W+'x'+Hh+'|'+P.seed+'|'+sty;
if(!S.tex||S.tk!==tkey){
  const g=(S.tex&&S.tex.width===W&&S.tex.height===Hh)?S.tex:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.strokeWeight(1);
  for(let i=0;i<680;i++){ const y=fr(i*11)*Hh, x=fr(i*11+1)*W, L=W*(.02+fr(i*11+2)*.16);
    g.stroke(0,0,fr(i*11+3)>.5?100:0, 4+fr(i*11+4)*7); g.line(x,y,x+L,y+(fr(i*11+5)-.5)*3); }
  g.noStroke();
  for(let i=0;i<900;i++){ const x=fr(i*23)*W, y=fr(i*23+1)*Hh;
    g.fill(0,0,fr(i*23+2)>.55?100:0, 3+fr(i*23+3)*7); g.circle(x,y,.8+fr(i*23+4)*2.4); }
  S.tex=g; S.tk=tkey; }
dc.globalCompositeOperation='overlay'; image(S.tex,0,0); dc.globalCompositeOperation=oldOp;

// ---- mineral crust speckle + efflorescence bloom ----
noStroke();
const NS=Math.round(120+dens*180);
dc.globalCompositeOperation='overlay';
for(let i=0;i<NS;i++){
  const x=fr(i*13), y=fr(i*13+1), a=smp(x,y);
  const ox=cl(a*(.35+corr*1.3),0,1); if(ox<.28) continue;
  const wob=.006*Math.sin(T*.23+i);
  fill(md(H+(sty==='rust'?34:sty==='lichen'?56:150),360), 24, fr(i*13+2)>.45?92:14, (10+30*ox)*al);
  ellipse((x+wob)*W,(y-wob*.7)*Hh, u*(.004+fr(i*13+3)*.016), u*(.004+fr(i*13+4)*.013));
}
dc.globalCompositeOperation=oldOp;

// ---- mineral run-off staining below the heaviest crust (drifts, MULTIPLY) ----
dc.globalCompositeOperation='multiply';
for(let i=0;i<10;i++){
  const x=((fr(i*29)+.05*Math.sin(T*.037+i*1.7))%1), y0=cl(P.y-.42+fr(i*29+1)*.62,.02,.78);
  const a=smp(x,y0+.02); if(a<.4) continue;
  const w2=u*(.012+fr(i*29+2)*.05), L=Hh*(.12+fr(i*29+3)*.4)*(.5+.6*en);
  const lg=dc.createLinearGradient(0,y0*Hh,0,y0*Hh+L);
  const cc=hsb2rgb(md(H+(sty==='rust'?24:sty==='silver_tarnish'?260:160),360),46,52);
  lg.addColorStop(0,'rgba('+(cc[0]|0)+','+(cc[1]|0)+','+(cc[2]|0)+','+(0.34*al).toFixed(3)+')');
  lg.addColorStop(1,'rgba(255,255,255,0)');
  dc.fillStyle=lg; dc.fillRect(x*W-w2/2, y0*Hh, w2, L);
}
dc.globalCompositeOperation=oldOp;

// ---- gallery sheen: slow specular pass over the whole plate ----
dc.globalCompositeOperation='lighter';
const sa=.22+.12*Math.sin(T*.029), ux=Math.cos(sa), uy=Math.sin(sa);
const L2=Math.abs(W*ux)+Math.abs(Hh*uy)+1, cpos=((T*.024)%1+1)%1*L2, bw=u*.2;
const ox2=W/2-(L2/2-cpos)*ux, oy2=Hh/2-(L2/2-cpos)*uy;
const lg2=dc.createLinearGradient(ox2-bw*ux,oy2-bw*uy,ox2+bw*ux,oy2+bw*uy);
lg2.addColorStop(0,'rgba(255,255,255,0)');
lg2.addColorStop(.5,'rgba(255,250,235,'+(0.025+0.05*en*al).toFixed(3)+')');
lg2.addColorStop(1,'rgba(255,255,255,0)');
dc.fillStyle=lg2; dc.fillRect(0,0,W,Hh);

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.shadowBlur=0; noStroke(); noTint();
